CREATE TABLE IF NOT EXISTS corpus_revisions (id UUID PRIMARY KEY, commit_sha TEXT NOT NULL UNIQUE, status TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ, validator_version TEXT NOT NULL, counts JSONB NOT NULL DEFAULT '{}'::jsonb, error_summary TEXT);
CREATE TABLE IF NOT EXISTS conversations (id UUID PRIMARY KEY, owner_account_id UUID NOT NULL REFERENCES accounts(id), title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id UUID PRIMARY KEY, conversation_id UUID NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, actor TEXT NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_items (id TEXT PRIMARY KEY, kind TEXT NOT NULL, corpus_revision_id UUID REFERENCES corpus_revisions(id), source_id TEXT, title TEXT NOT NULL, locator TEXT, url TEXT, publisher TEXT, authority TEXT NOT NULL, applicability TEXT, version_or_date TEXT, captured_at TIMESTAMPTZ NOT NULL, excerpt TEXT NOT NULL, digest TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS answers (id UUID PRIMARY KEY, message_id UUID REFERENCES messages(id), corpus_revision_id UUID REFERENCES corpus_revisions(id), primary_profile_id UUID REFERENCES agent_profiles(id), reviewer_profile_id UUID REFERENCES agent_profiles(id), review_mode TEXT NOT NULL, review_status TEXT NOT NULL, direct_answer TEXT NOT NULL, steps JSONB NOT NULL, safety_assumptions JSONB NOT NULL, confidence TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS answer_claims (id UUID PRIMARY KEY, answer_id UUID NOT NULL REFERENCES answers(id) ON DELETE CASCADE, ordinal INTEGER NOT NULL, text TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, rationale_code TEXT, UNIQUE(answer_id, ordinal));
CREATE TABLE IF NOT EXISTS claim_evidence (claim_id UUID NOT NULL REFERENCES answer_claims(id) ON DELETE CASCADE, evidence_item_id TEXT NOT NULL REFERENCES evidence_items(id), PRIMARY KEY(claim_id, evidence_item_id));
CREATE TABLE IF NOT EXISTS feedback (id UUID PRIMARY KEY, answer_id UUID NOT NULL REFERENCES answers(id), account_id UUID NOT NULL REFERENCES accounts(id), rating TEXT NOT NULL, reason TEXT, comment TEXT, question_fingerprint TEXT NOT NULL, corpus_commit TEXT NOT NULL, profile_revision_ids JSONB NOT NULL, evidence_ids JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS training_examples (id UUID PRIMARY KEY, feedback_id UUID REFERENCES feedback(id), state TEXT NOT NULL, content JSONB NOT NULL, author_id UUID NOT NULL REFERENCES accounts(id), reviewer_id UUID REFERENCES accounts(id), created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS web_findings (id UUID PRIMARY KEY, url TEXT NOT NULL, publisher TEXT, captured_at TIMESTAMPTZ NOT NULL, digest TEXT NOT NULL, excerpt TEXT NOT NULL, authority TEXT NOT NULL, review_state TEXT NOT NULL, flagger_id UUID NOT NULL REFERENCES accounts(id), reviewer_id UUID REFERENCES accounts(id), notes TEXT);
CREATE TABLE IF NOT EXISTS change_proposals (id UUID PRIMARY KEY, proposer_id UUID NOT NULL REFERENCES accounts(id), reviewer_id UUID REFERENCES accounts(id), rationale TEXT NOT NULL, target_repository TEXT NOT NULL, base_commit TEXT NOT NULL, target_path TEXT NOT NULL, operation TEXT NOT NULL, proposed_content TEXT NOT NULL, content_digest TEXT NOT NULL, state TEXT NOT NULL, branch_name TEXT, commit_sha TEXT, pull_request_url TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS jobs (id UUID PRIMARY KEY, kind TEXT NOT NULL, payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'READY', attempts INTEGER NOT NULL DEFAULT 0, available_at TIMESTAMPTZ NOT NULL, lease_owner TEXT, lease_expires_at TIMESTAMPTZ, last_error_code TEXT, last_error_message TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS jobs_lease_idx ON jobs(status, available_at, lease_expires_at);
